const fs = require('fs');

function gcd(a, b) {
    if (a > b) {
        [a, b] = [b, a];
    }

    if (a === 0 || b === 0) {
        return a + b;
    }

    let result = 1;

    while (true) {
        const remain = b % a;

        if (remain === 0) {
            result *= a;
            break;
        } else {
            b = a;
            a = remain;
        }
    }
    return result;
}

