    // Simon plays
    const simonQuota = gcd(simon, currentStones);

    if (simonQuota <= currentStones) {
        currentStones -= simonQuota;
    } else {
        console.log(1);
        break;
    }

    // Antisimon plays
    const antiQuota = gcd(antisimon, currentStones);

    if (antiQuota <= currentStones) {
        currentStones -= antiQuota;
    } else {
        console.log(0);
        break;
    }
}

