	var simon, antisimon, stones int

	fmt.Scanf("%d %d %d", &simon, &antisimon, &stones)

	for {
		// Simon plays
		var simonQuota = gcd(simon, stones)

		if simonQuota <= stones {
			stones -= simonQuota
		} else {
			fmt.Println(1)
			return
		}

		// Antisimon plays
		var antiQuota = gcd(antisimon, stones)

		if antiQuota <= stones {
			stones -= antiQuota
		} else {
			fmt.Println(0)
			return
